-- Generated by tools/build-owner-samples.py. Run the COMPLETE file in Supabase SQL Editor.
-- Requires owner-access.sql. Adds four requested samples to the pinned Owner's shop.
-- Preserves all existing accounts, products, images, prices, and account permissions.
begin;

-- Approved Buyers can browse the Owner's catalog without making the Owner a Seller.
create or replace function public.lk_catalog_owner_is_approved(account_id uuid)
returns boolean language sql stable security definer set search_path='' as $$
 select public.lk_seller_is_approved(account_id) or lk_private.is_owner_id(account_id);
$$;
revoke all on function public.lk_catalog_owner_is_approved(uuid) from public,anon,authenticated;
grant execute on function public.lk_catalog_owner_is_approved(uuid) to authenticated;
alter policy lk_member_shops on public.lk_shops
 using ((select public.lk_has_store_access()) and public.lk_catalog_owner_is_approved(owner_id));
alter policy lk_member_products on public.lk_products
 using ((select public.lk_has_store_access()) and public.lk_catalog_owner_is_approved(owner_id)
 and (status='active' or owner_id=(select auth.uid())));

do $import$
declare
 owner_profile public.lk_profiles;
 item jsonb;
 product_key text;
 stamp text:=to_char(now() at time zone 'UTC','YYYY-MM-DD"T"HH24:MI:SS.US"Z"');
begin
 perform pg_advisory_xact_lock(730412);
 select p.* into owner_profile from public.lk_profiles p
 join lk_private.owner_account o on o.auth_id=p.auth_id
 where p.role='customer' and p.username='scorpion' and p.verification_status='approved';
 if not found then raise exception 'Activate the protected Scorpion Owner account first.'; end if;

 insert into public.lk_shops(id,owner_id,profile) values(owner_profile.id,owner_profile.auth_id,
  jsonb_build_object('id',owner_profile.id,'name','Scorpion Tech - Owner Store',
  'tagline','A selection of sample tech products.',
  'description','Sample listings curated for the LK Tech Store preview. Photos are illustrative; prices and stock are demonstration values.',
  'email','','phone','','location','','color','#c5a6f5'))
 on conflict (id) do nothing;
 if not exists(select 1 from public.lk_shops where id=owner_profile.id and owner_id=owner_profile.auth_id) then
  raise exception 'Owner storefront identity mismatch; nothing has been imported.';
 end if;

 for item in select value from jsonb_array_elements($catalog$[{"id":"product_49b14f38355757fb999fdfddbd6da5d0","name":"Studio Wireless Headphones (Sample)","summary":"Sample listing: an over-ear audio pick for your everyday setup.","description":"A sample over-ear headphone listing for exploring the store. The photograph is illustrative; the name, price, and stock are demonstration values, not an offer for the pictured brand or model.\n\nPhoto: Totte Annerbrink / Unsplash.","category":"Tech","price":79.99,"priceCents":7999,"stock":10,"status":"active","sku":"OWNER-SAMPLE-HEADPHONES","image":"data:image/jpeg;base64,","color":"#e7dbed","isNew":true,"isCustom":true,"isSample":true,"sampleCollection":"owner-tech-v1","imageCredit":"Totte Annerbrink","imageSource":"https://unsplash.com/photos/black-wireless-headphones-NehdOHCXsjs"},{"id":"product_d67977254dea5f1495f02bb5fd7bf4d5","name":"Glow Mechanical Keyboard (Sample)","summary":"Sample listing: illuminated keys for a colorful desk setup.","description":"A sample mechanical keyboard listing with an illuminated-key photograph. The photograph is illustrative; the name, price, and stock are demonstration values, not an offer for a specific model.\n\nPhoto: Christian Wiediger / Unsplash.","category":"Tech","price":59.99,"priceCents":5999,"stock":10,"status":"active","sku":"OWNER-SAMPLE-KEYBOARD","image":"data:image/jpeg;base64,","color":"#d5dfeb","isNew":true,"isCustom":true,"isSample":true,"sampleCollection":"owner-tech-v1","imageCredit":"Christian Wiediger","imageSource":"https://unsplash.com/photos/closeup-photo-of-computer-keyboard-WkfDrhxDMC8"},{"id":"product_748c23ca34f950a2aa97c4b9826e0701","name":"Precision Wireless Mouse (Sample)","summary":"Sample listing: a minimal wireless mouse for your workspace.","description":"A sample wireless mouse listing for browsing, search, and cart previews. The photograph is illustrative; the name, price, and stock are demonstration values, not an offer for the pictured brand or model.\n\nPhoto: Pascal M. / Unsplash.","category":"Tech","price":29.99,"priceCents":2999,"stock":10,"status":"active","sku":"OWNER-SAMPLE-MOUSE","image":"data:image/jpeg;base64,","color":"#d7e2da","isNew":true,"isCustom":true,"isSample":true,"sampleCollection":"owner-tech-v1","imageCredit":"Pascal M.","imageSource":"https://unsplash.com/photos/black-cordless-computer-mouse-on-black-surface-4PchFKrUw84"},{"id":"product_76050a8c92be521c8df1b71af77a0909","name":"Home Desktop Speaker (Sample)","summary":"Sample listing: a clean, compact speaker for a modern room.","description":"A sample desktop speaker listing with a clean white finish. The photograph is illustrative; the name, price, and stock are demonstration values, not an offer for the pictured brand or model.\n\nPhoto: Andres Jasso / Unsplash.","category":"Tech","price":49.99,"priceCents":4999,"stock":10,"status":"active","sku":"OWNER-SAMPLE-SPEAKER","image":"data:image/jpeg;base64,","color":"#e8ddce","isNew":true,"isCustom":true,"isSample":true,"sampleCollection":"owner-tech-v1","imageCredit":"Andres Jasso","imageSource":"https://unsplash.com/photos/white-bluetooth-speaker-iVcd6fyPIFE"}]$catalog$::jsonb) loop
  product_key:=item->>'id';
  if exists(select 1 from public.lk_products where id=product_key and
    (owner_id<>owner_profile.auth_id or seller_id<>owner_profile.id or data->>'sku' is distinct from item->>'sku')) then
   raise exception 'Sample product identity conflict; nothing has been imported.';
  end if;
  -- Same-owner SKU matches and previously imported IDs are preserved on reruns.
  if not exists(select 1 from public.lk_products where id=product_key or
    (seller_id=owner_profile.id and lower(data->>'sku')=lower(item->>'sku'))) then
   insert into public.lk_products(id,seller_id,owner_id,data)
   values(product_key,owner_profile.id,owner_profile.auth_id,
    item||jsonb_build_object('sellerId',owner_profile.id,'image',lk_private.image(item->'image'),
    'createdAt',stamp,'updatedAt',stamp));
  end if;
 end loop;
end $import$;
commit;

select p.data->>'name' as product,p.data->>'price' as price_usd,p.status
from public.lk_products p join lk_private.owner_account o on o.auth_id=p.owner_id
where p.data->>'sampleCollection'='owner-tech-v1' order by p.data->>'name';
